def main() -> None:
    path = ROOT / "content" / "posts.json"
    posts = json.loads(path.read_text(encoding="utf-8"))
    for post in posts:
        title, summary, intro, sections, takeaway_title, takeaway = EDITION[post["slug"]]
        post.update({
            "title": title,
            "seo_title": title,
            "summary": summary,
            "subject": f"استفسار حول {title}",
            "intro": [intro],
            "sections": [
                {"heading": heading, "paragraphs": [paragraph], "bullets": bullets}
                for heading, paragraph, bullets in sections
            ],
            "takeaway_title": takeaway_title,
            "takeaway": takeaway,
            "published": "2026-10-18",
        })
        if post.get("featured"):
            post["featured"]["alt"] = f"صورة توضيحية لمقال {title} من أوركيد لحلول التقنية"
    path.write_text(json.dumps(posts, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Rewrote {len(posts)} Orkeed posts")


if __name__ == "__main__":
    main()
